def compute(vars):
    high_price = vars["v1"]
    low_price = vars["v2"]
    value = (high_price + low_price) / 2
    return {
        "value": value,
        "trace": {
            "high_price": high_price,
            "low_price": low_price,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency/share"
            }
        }
    }
